PLANILHA_SALDOS_ID = "1NFHtHLaBdzukM0JltkzEExro8zZj1ktD"
PLANILHA_SALDOS_LINK = (
    f"https://docs.google.com/spreadsheets/d/{PLANILHA_SALDOS_ID}/edit"
    "?usp=sharing&ouid=116238154054352363368&rtpof=true&sd=true"
)

MESES_PLANILHA = {
    1: "JANEIRO", 2: "FEVEREIRO", 3: "MARÇO", 4: "ABRIL",
    5: "MAIO", 6: "JUNHO", 7: "JULHO", 8: "AGOSTO",
    9: "SETEMBRO", 10: "OUTUBRO", 11: "NOVEMBRO", 12: "DEZEMBRO",
}

# GIDs conhecidos. O mês vigente é selecionado automaticamente por date.today().month.
# Quando o GID estiver cadastrado, ele é prioritário. Nos demais meses, o código
# consulta pelo nome da aba, mantendo a troca automática de mês.
GIDS_MESES = {
    8: "795983242",  # AGOSTO
}

MESES_TEXTO = {
    "JANEIRO": 1, "FEVEREIRO": 2, "MARCO": 3, "ABRIL": 4,
    "MAIO": 5, "JUNHO": 6, "JULHO": 7, "AGOSTO": 8,
    "SETEMBRO": 9, "OUTUBRO": 10, "NOVEMBRO": 11, "DEZEMBRO": 12,
}


def _normalizar_simples(valor: object) -> str:
    texto = "" if valor is None else str(valor)
    texto = unicodedata.normalize("NFKD", texto).encode("ascii", "ignore").decode("ascii")
    return re.sub(r"\s+", " ", texto.strip().upper())


def _data_saldo(valor: object, ano: int, mes_padrao: int) -> pd.Timestamp:
    """Aceita datas reais, DD/MM/AAAA, DD/MM, dia isolado e textos '03 DE AGOSTO'."""
    if valor is None or (isinstance(valor, float) and pd.isna(valor)):
        return pd.NaT

    if isinstance(valor, (pd.Timestamp, date)):
        data = pd.Timestamp(valor).normalize()
        if data.year == 1900:
            data = pd.Timestamp(year=ano, month=mes_padrao, day=data.day)
        return data

    texto_original = str(valor).strip()
    if not texto_original:
        return pd.NaT

    # Formato do Google Visualization: Date(2026,7,3), com mês iniciado em zero.
    match_date = re.search(r"Date\((\d{4}),\s*(\d{1,2}),\s*(\d{1,2})\)", texto_original)
    if match_date:
        return pd.Timestamp(
            year=int(match_date.group(1)),
            month=int(match_date.group(2)) + 1,
            day=int(match_date.group(3)),
        )

    texto = _normalizar_simples(texto_original)
    match_extenso = re.search(r"(\d{1,2})\s+DE\s+([A-Z]+)(?:\s+DE\s+(\d{4}))?", texto)
    if match_extenso:
        dia = int(match_extenso.group(1))
        mes = MESES_TEXTO.get(match_extenso.group(2), mes_padrao)
        ano_data = int(match_extenso.group(3)) if match_extenso.group(3) else ano
        try:
            return pd.Timestamp(year=ano_data, month=mes, day=dia)
        except ValueError:
            return pd.NaT

    # Formato exibido pelo Google Sheets quando a célula usa uma data abreviada:
    # "3-ago", "03/ago" ou "3 ago". O CSV do endpoint gviz devolve o texto
    # formatado, e não necessariamente o valor Date(...) interno.
    match_mes_abreviado = re.fullmatch(
        r"(\d{1,2})[\s./-]+([A-Z]{3,9})(?:[\s./-]+(\d{2,4}))?",
        texto,
    )
    if match_mes_abreviado:
        dia = int(match_mes_abreviado.group(1))
        nome_mes = match_mes_abreviado.group(2)
        meses_abreviados = {
            nome[:3]: numero
            for nome, numero in MESES_TEXTO.items()
        }
        mes = MESES_TEXTO.get(nome_mes, meses_abreviados.get(nome_mes[:3]))
        if mes is not None:
            ano_texto = match_mes_abreviado.group(3)
            ano_data = int(ano_texto) if ano_texto else ano
            if ano_texto and len(ano_texto) == 2:
                ano_data += 2000
            try:
                return pd.Timestamp(year=ano_data, month=mes, day=dia)
            except ValueError:
                return pd.NaT

    # Dia isolado, comum quando a célula está formatada apenas para exibir o dia.
    if re.fullmatch(r"\d{1,2}", texto):
        try:
            return pd.Timestamp(year=ano, month=mes_padrao, day=int(texto))
        except ValueError:
            return pd.NaT

    # DD/MM sem ano.
    match_curto = re.fullmatch(r"(\d{1,2})[/-](\d{1,2})", texto)
    if match_curto:
        try:
            return pd.Timestamp(year=ano, month=int(match_curto.group(2)), day=int(match_curto.group(1)))
        except ValueError:
            return pd.NaT

    convertido = pd.to_datetime(texto_original, errors="coerce", dayfirst=True)
    if pd.isna(convertido):
        return pd.NaT
    convertido = pd.Timestamp(convertido).normalize()
    if convertido.year == 1900:
        convertido = pd.Timestamp(year=ano, month=mes_padrao, day=convertido.day)
    return convertido


def _valor_saldo(valor: object) -> float | None:
    """Converte valores numéricos e textos monetários brasileiros/americanos."""
    if valor is None or (isinstance(valor, float) and pd.isna(valor)):
        return None
    if isinstance(valor, (int, float, np.number)):
        return float(valor)

    texto = str(valor).strip()
    if not texto:
        return None

    negativo_parenteses = texto.startswith("(") and texto.endswith(")")
    texto = texto.replace("R$", "").replace(" ", "").replace("\u00a0", "")
    texto = re.sub(r"[^0-9,\.\-]", "", texto)
    if not texto or texto in {"-", ".", ","}:
        return None

    if "," in texto and "." in texto:
        # O último separador é tratado como decimal.
        if texto.rfind(",") > texto.rfind("."):
            texto = texto.replace(".", "").replace(",", ".")
        else:
            texto = texto.replace(",", "")
    elif "," in texto:
        partes = texto.split(",")
        texto = "".join(partes[:-1]) + "." + partes[-1] if len(partes[-1]) <= 2 else "".join(partes)
    elif texto.count(".") > 1:
        partes = texto.split(".")
        texto = "".join(partes[:-1]) + "." + partes[-1] if len(partes[-1]) <= 2 else "".join(partes)

    try:
        numero = float(texto)
    except ValueError:
        return None
    return -abs(numero) if negativo_parenteses else numero


@st.cache_data(ttl=60, show_spinner=False)
def baixar_aba_saldos(mes: int, nome_aba: str, gid: str | None) -> pd.DataFrame:
    """Lê A4:L31 da aba vigente. Prioriza GID e usa nome da aba como contingência."""
    base = f"https://docs.google.com/spreadsheets/d/{PLANILHA_SALDOS_ID}/gviz/tq"
    parametros = ["tqx=out:csv", "range=A4:L31"]
    if gid:
        parametros.append(f"gid={gid}")
        fonte = f"GID {gid}"
    else:
        from urllib.parse import quote
        parametros.append(f"sheet={quote(nome_aba)}")
        fonte = f"aba {nome_aba}"
    parametros.append(f"cache_bust={pd.Timestamp.utcnow().value}")
    url = base + "?" + "&".join(parametros)

    resposta = requests.get(
        url,
        timeout=60,
        allow_redirects=True,
        headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
            "Cache-Control": "no-cache, no-store, must-revalidate",
            "Pragma": "no-cache",
        },
    )
    resposta.raise_for_status()
    conteudo = resposta.content
    tipo = resposta.headers.get("Content-Type", "").lower()

    if not conteudo:
        raise RuntimeError(f"A consulta da {fonte} retornou conteúdo vazio.")
    if b"<html" in conteudo[:500].lower() or "text/html" in tipo:
        raise RuntimeError(
            "O Google devolveu uma página HTML em vez dos dados. "
            "Confirme que a planilha está disponível para qualquer pessoa com o link."
        )

    try:
        quadro = pd.read_csv(
            io.BytesIO(conteudo),
            header=None,
            dtype=str,
            keep_default_na=False,
        )
    except Exception as exc:
        raise RuntimeError(f"Não foi possível interpretar os dados da {fonte}: {exc}") from exc

    # O CSV pode omitir colunas vazias à direita; garante sempre A:L.
    quadro = quadro.reindex(columns=range(12), fill_value="")
    quadro.attrs["fonte"] = fonte
    quadro.attrs["url_consulta"] = url
    return quadro


def buscar_saldo_drive(data_referencia: date | None = None) -> dict:
    """Busca exclusivamente o saldo mais recente da aba do mês vigente."""
    referencia = data_referencia or date.today()
    mes = referencia.month
    nome_aba = MESES_PLANILHA[mes]
    gid = GIDS_MESES.get(mes)

    quadro = baixar_aba_saldos(mes, nome_aba, gid)
    registros: list[dict] = []

    for indice, linha in quadro.iterrows():
        linha_planilha = int(indice) + 4
        data_valor = _data_saldo(linha.iloc[0], referencia.year, mes)
        saldo_valor = _valor_saldo(linha.iloc[11])

        if pd.isna(data_valor) or saldo_valor is None:
            continue
        data_obj = pd.Timestamp(data_valor).date()
        if data_obj.year != referencia.year or data_obj.month != mes or data_obj > referencia:
            continue

        registros.append({
            "Data": pd.Timestamp(data_valor),
            "Saldo": float(saldo_valor),
            "Linha": linha_planilha,
        })

    if not registros:
        identificador = f"GID {gid}" if gid else f"nome {nome_aba}"
        raise ValueError(
            f"Nenhum saldo válido foi encontrado na aba vigente {nome_aba} ({identificador}), "
            f"entre A4:A31 e L4:L31, até {referencia:%d/%m/%Y}. "
            "Confira se as datas estão na coluna A e o saldo total na coluna L da mesma linha."
        )

    base = pd.DataFrame(registros).sort_values(["Data", "Linha"])
    ultimo = base.iloc[-1]

    return {
        "saldo": float(ultimo["Saldo"]),
        "data_saldo": pd.Timestamp(ultimo["Data"]).date(),
        "data_referencia": referencia,
        "origem": "Último saldo preenchido no mês vigente",
        "aba": nome_aba,
        "linha": int(ultimo["Linha"]),
        "gid": gid,
        "fonte": quadro.attrs.get("fonte", nome_aba),
    }


def norm_text(value: object) -> str:
    txt = "" if value is None else str(value)
    txt = unicodedata.normalize("NFKD", txt).encode("ascii", "ignore").decode("ascii")
    return re.sub(r"\s+", " ", txt.strip().upper())


def money_br(value: float) -> str:
    if pd.isna(value):
        return "R$ 0,00"
    sign = "-" if float(value) < 0 else ""
    txt = f"{abs(float(value)):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return f"{sign}R$ {txt}"


def number_br(series: pd.Series) -> pd.Series:
    return pd.to_numeric(
        series.astype(str)
        .str.replace(r"[^0-9,.-]", "", regex=True)
        .str.replace(".", "", regex=False)
        .str.replace(",", ".", regex=False),
        errors="coerce",
    )


def read_raw_bytes(uploaded) -> bytes:
    uploaded.seek(0)
    return uploaded.read()


def decode_file(data: bytes) -> str:
    for enc in ("utf-8-sig", "cp1252", "latin1"):
        try:
            return data.decode(enc)
        except UnicodeDecodeError:
            continue
    return data.decode("latin1", errors="replace")


def find_header_line(lines: list[str], required_any: Iterable[str]) -> int:
    terms = [norm_text(x) for x in required_any]
    for idx, line in enumerate(lines):
        if ";" in line and any(term in norm_text(line) for term in terms):
            return idx
    raise ValueError("Não foi possível localizar o cabeçalho da tabela.")


def read_report_csv(data: bytes, expected: str) -> pd.DataFrame:
    signatures = {
        "cartoes": ["VLR.LIQ", "VLR LIQ", "DTA.VEN"],
        "receber": ["V.LIQUI", "CLIENTE", "VENCTO"],
        "pagar": ["VAL.LIQ", "FORNECEDOR", "DTA.VEN"],
    }
    lines = decode_file(data).splitlines()
    header_idx = find_header_line(lines, signatures[expected])
    df = pd.read_csv(
        io.StringIO("\n".join(lines[header_idx:])),
        sep=";", dtype=str, engine="python", on_bad_lines="skip",
    )
    df.columns = [norm_text(c) for c in df.columns]
    return df.dropna(how="all")


def first_existing(df: pd.DataFrame, candidates: list[str]) -> str:
    direct = {norm_text(c): c for c in df.columns}
    for candidate in candidates:
        if norm_text(candidate) in direct:
            return direct[norm_text(candidate)]
    for candidate in candidates:
        target = norm_text(candidate)
        for col in df.columns:
            if target in norm_text(col):
                return col
    raise ValueError(f"Coluna não encontrada: {', '.join(candidates)}")


def safe_column(raw: pd.DataFrame, candidates: list[str]) -> pd.Series:
    try:
        return raw[first_existing(raw, candidates)].fillna("").astype(str)
    except ValueError:
        return pd.Series("", index=raw.index, dtype="object")


def parse_source(data: bytes, source: str) -> pd.DataFrame:
    raw = read_report_csv(data, source)
    blank = pd.Series("", index=raw.index, dtype="object")
    document = origin_document = nsu = seller = account = account_name = history = result_account = blank.copy()

    if source == "cartoes":
        date_col = first_existing(raw, ["DTA.VEN", "DTA VEN", "VENCIMENTO"])
        value_col = first_existing(raw, ["VLR.LIQ", "VLR LIQ", "VALOR LIQUIDO"])
        company_col = first_existing(raw, ["EMP", "LOJ"])
        counterpart = safe_column(raw, ["CARTAO", "CARTÃO", "BANDEIRA", "ADMINISTRADORA"])
        counterpart = counterpart.mask(counterpart.str.strip().eq(""), "Recebimentos de cartão")
        document = safe_column(raw, ["DUPLICATA"])
        origin_document = safe_column(raw, ["DOC.ORIG", "DOC ORIG"])
        nsu = safe_column(raw, ["NUM.NSU", "NUM NSU", "NRO. NSU"])
        seller = safe_column(raw, ["VENDEDOR"])
        movement, nature = "Cartões", "Entrada"

    elif source == "receber":
        date_col = first_existing(raw, ["VENCTO", "VENCIMENTO", "DTA.VEN"])
        value_col = first_existing(raw, ["V.LIQUI", "V LIQUI", "VALOR LIQUIDO"])
        company_col = first_existing(raw, ["LOJ", "EMP"])
        counterpart = raw[first_existing(raw, ["CLIENTE"])].fillna("").astype(str)
        document = safe_column(raw, ["DUPLICATA", "DOCUMENTO"])
        history = safe_column(raw, ["HISTORICO", "HISTÓRICO"])
        seller = safe_column(raw, ["VEN", "VENDEDOR"])
        movement, nature = "Títulos a receber", "Entrada"

    else:
        date_col = first_existing(raw, ["DTA.VEN", "VENCIMENTO"])
        # O relatório "TÍTULOS POR PLANO DE CONTAS - ANALÍTICO" utiliza VAL.DUP
        # como valor do título. Mantém compatibilidade com formatos antigos que
        # traziam VAL.LIQ / VALOR LÍQUIDO.
        value_col = first_existing(raw, ["VAL.LIQ", "VAL LIQ", "VALOR LIQUIDO", "VAL.DUP", "VAL DUP", "VALOR DUPLICATA"])
        company_col = first_existing(raw, ["LOJ", "EMP"])
        counterpart = raw[first_existing(raw, ["FAVORECIDO", "FORNECEDOR"])].fillna("").astype(str)
        document = safe_column(raw, ["DUPLICATA", "DOCUMENTO"])

        # Formato correto do relatório atual do Autcom:
        #   Coluna A = CONTA DE RESULTADO (ex.: 00017 - DESPESAS OPERACIONAIS)
        #   Coluna B = PLANO DE CONTAS (ex.: 02.07.001-ICMS (3 - DESPESAS))
        #   Coluna C = FAVORECIDO
        # O cabeçalho da coluna B pode vir vazio ("Unnamed: 1" após leitura pelo pandas),
        # portanto ela é capturada por posição quando a coluna A é CONTA DE RESULTADO.
        result_account = safe_column(raw, [
            "CONTA DE RESULTADO", "CONTA RESULTADO", "GRUPO DE RESULTADO", "GRUPO RESULTADO"
        ])
        is_result_report = (
            raw.shape[1] >= 3
            and norm_text(raw.columns[0]) in {"CONTA DE RESULTADO", "CONTA RESULTADO"}
            and "FAVORECIDO" in [norm_text(c) for c in raw.columns]
        )

        if is_result_report:
            # A Conta de Resultado é impressa apenas na primeira linha do grupo;
            # forward-fill replica o agrupador para todos os títulos subsequentes.
            first_col = raw.iloc[:, 0].fillna("").astype(str).str.replace(r"\s+", " ", regex=True).str.strip()
            result_account = first_col.replace("", pd.NA).ffill().fillna("SEM CONTA DE RESULTADO")

            # A coluna B contém o Plano de Contas completo (código + nomenclatura).
            account = raw.iloc[:, 1].fillna("").astype(str).str.replace(r"\s+", " ", regex=True).str.strip()
            account_name = account.copy()
        else:
            account = safe_column(raw, ["CONTA", "PLANO DE CONTAS"])
            account_name = safe_column(raw, [
                "NOMENCLATURA", "NOMENCLATURA CONTA", "NOME CONTA",
                "DESCRICAO CONTA", "DESCRIÇÃO CONTA",
            ])

        history = safe_column(raw, ["HISTORICO", "HISTÓRICO", "DESCRICAO", "DESCRIÇÃO"])
        if history.str.strip().eq("").all() and raw.shape[1] >= 13:
            history = raw.iloc[:, -1].fillna("").astype(str)
        movement, nature = "Títulos a pagar", "Saída"

    out = pd.DataFrame({
        "Data": pd.to_datetime(raw[date_col], dayfirst=True, errors="coerce"),
        "Valor": number_br(raw[value_col]),
        "Empresa": raw[company_col].fillna("").astype(str).str.strip(),
        "Contraparte": counterpart.fillna("").astype(str).str.replace(r"\s+", " ", regex=True).str.strip(),
        "Documento": document.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Documento de origem": origin_document.str.replace(r"\s+", " ", regex=True).str.strip(),
        "NSU": nsu.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Vendedor": seller.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Conta": account.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Conta de Resultado": result_account.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Nomenclatura da Conta": account_name.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Histórico": history.str.replace(r"\s+", " ", regex=True).str.strip(),
        "Origem": movement,
        "Natureza": nature,
    }).dropna(subset=["Data", "Valor"])

    # Duplicatas internas de títulos a receber terminadas em “-TE” não representam
    # recebimentos externos e, portanto, são excluídas automaticamente do fluxo.
    if source == "receber":
        documento_normalizado = out["Documento"].fillna("").astype(str).str.strip().str.upper()
        out = out[~documento_normalizado.str.contains(r"-TE\s*$", regex=True, na=False)].copy()

    # Transações internas entre empresas do grupo não devem compor a agenda,
    # a projeção nem os indicadores de contas a pagar. A comparação é feita
    # de forma normalizada para tolerar códigos de fornecedor, acentos, caixa
    # e espaços extras no relatório exportado pelo ERP.
    if source == "pagar":
        internal_payable_parties = [
            "DT TINTAS COMERCIO VAREJISTA LIMITADA",
            "MERCADO DAS TINTAS LTDA",
            "V&T COMERCIO VAREJISTA DE TINTAS LTDA",
            "ETICA COMERCIO VAREJISTA DE TINTAS",
        ]
        counterpart_normalized = out["Contraparte"].fillna("").astype(str).map(norm_text)
        counterpart_normalized = counterpart_normalized.str.replace(
            r"^\d+\s*[-–—]\s*", "", regex=True
        )
        internal_mask = pd.Series(False, index=out.index)
        for party in internal_payable_parties:
            internal_mask |= counterpart_normalized.str.contains(
                re.escape(norm_text(party)), regex=True, na=False
            )
        out = out[~internal_mask].copy()

    out = out[out["Valor"].ne(0)].copy()
    out["Entrada"] = np.where(out["Natureza"].eq("Entrada"), out["Valor"], 0.0)
    out["Saída"] = np.where(out["Natureza"].eq("Saída"), out["Valor"], 0.0)
    return out.sort_values("Data").reset_index(drop=True)


def join_unique(series: pd.Series) -> str:
    values = [str(v).strip() for v in series if pd.notna(v) and str(v).strip()]
    return " | ".join(dict.fromkeys(values))


def consolidate_documents(df: pd.DataFrame) -> pd.DataFrame:
    if df.empty:
        return df.copy()
    work = df.copy()
    work["Documento-chave"] = work["Documento"].fillna("").astype(str).str.strip()
    empty = work["Documento-chave"].eq("")
    work.loc[empty, "Documento-chave"] = "SEM_DOC_" + work.index[empty].astype(str)
    groups = ["Origem", "Natureza", "Data", "Documento-chave"]
    # Preserva também a nomenclatura da Conta de Resultado durante a consolidação.
    # Algumas origens não trazem essa coluna; nesses casos ela é criada vazia
    # para manter o schema estável em todas as telas e drills.
    for optional_col in ["Conta de Resultado", "Nomenclatura da Conta", "Histórico"]:
        if optional_col not in work.columns:
            work[optional_col] = ""

    result = work.groupby(groups, as_index=False, dropna=False).agg({
        "Valor": "sum", "Entrada": "sum", "Saída": "sum", "Empresa": join_unique,
        "Contraparte": join_unique, "Documento": join_unique, "Documento de origem": join_unique,
        "NSU": join_unique, "Vendedor": join_unique, "Conta": join_unique,
        "Conta de Resultado": join_unique, "Nomenclatura da Conta": join_unique, "Histórico": join_unique,
    })
    result["Quantidade de lançamentos"] = work.groupby(groups, dropna=False).size().to_numpy()
    return result.drop(columns="Documento-chave").sort_values(["Data", "Natureza", "Valor"], ascending=[True, True, False])


def aggregate_cashflow(df: pd.DataFrame, opening_balance: float, frequency: str) -> pd.DataFrame:
    if df.empty:
        return pd.DataFrame(columns=["Período", "Entradas", "Saídas", "Resultado", "Saldo Projetado"])
    temp = df.copy()
    if frequency == "Diário":
        temp["Período"] = temp["Data"].dt.normalize()
        grouped = temp.groupby("Período", as_index=False)[["Entrada", "Saída"]].sum()
        full = pd.DataFrame({"Período": pd.date_range(grouped["Período"].min(), grouped["Período"].max(), freq="D")})
        grouped = full.merge(grouped, on="Período", how="left").fillna({"Entrada": 0, "Saída": 0})
    elif frequency == "Semanal":
        temp["Período"] = temp["Data"].dt.to_period("W-MON").apply(lambda p: p.start_time)
        grouped = temp.groupby("Período", as_index=False)[["Entrada", "Saída"]].sum()
    else:
        temp["Período"] = temp["Data"].dt.to_period("M").dt.to_timestamp()
        grouped = temp.groupby("Período", as_index=False)[["Entrada", "Saída"]].sum()
    grouped = grouped.rename(columns={"Entrada": "Entradas", "Saída": "Saídas"}).sort_values("Período")
    grouped["Resultado"] = grouped["Entradas"] - grouped["Saídas"]
    grouped["Saldo Projetado"] = opening_balance + grouped["Resultado"].cumsum()
    return grouped


def format_period(value: pd.Timestamp, frequency: str) -> str:
    if frequency == "Diário":
        return value.strftime("%d/%m/%Y")
    if frequency == "Semanal":
        return f"{value:%d/%m} a {(value + timedelta(days=6)):%d/%m/%Y}"
    return value.strftime("%m/%Y")


def kpi_card(label: str, value: str, note: str, css_class: str) -> None:
    st.markdown(
        f'<div class="kpi-card {css_class}"><div class="kpi-label">{label}</div>'
        f'<div class="kpi-value">{value}</div><div class="kpi-note">{note}</div></div>',
        unsafe_allow_html=True,
    )


def render_financial_calendar(
    month_period: pd.Period,
    day_values: dict[int, dict[str, float]],
    mode: str = "finance",
    selected_start: date | None = None,
    selected_end: date | None = None,
) -> None:
    """Renderiza o mesmo calendário executivo para entradas, saídas e visão geral."""
    import calendar as _calendar

    weeks = _calendar.Calendar(firstweekday=0).monthdayscalendar(
        month_period.year, month_period.month
    )
    html = ['<div class="calendar-wrap"><div class="calendar-grid">']
    for name in ["Seg", "Ter", "Qua", "Qui", "Sex", "Sáb", "Dom"]:
        html.append(f'<div class="calendar-head">{name}</div>')

    for week in weeks:
        for day_number in week:
            if not day_number:
                html.append('<div class="calendar-day empty"></div>')
                continue

            current_date = date(month_period.year, month_period.month, day_number)
            values = day_values.get(day_number, {})
            entries = float(values.get("Entradas", 0.0))
            overdue = float(values.get("Atraso", 0.0))
            exits = float(values.get("Saídas", 0.0))
            balance = values.get("Saldo")

            selected = bool(
                selected_start and selected_end
                and selected_start <= current_date <= selected_end
            )
            if mode == "entries":
                state_class = "entry-focus"
                dot_class = "dot-warn" if overdue else "dot-pos"
            elif mode == "exits":
                if current_date < date.today():
                    state_class = "positive"
                    dot_class = "dot-pos"
                else:
                    state_class = "exit-focus"
                    dot_class = "dot-neg" if exits else "dot-pos"
            elif balance is not None and float(balance) < 0:
                state_class, dot_class = "negative", "dot-neg"
            elif balance is not None and minimum_cash > 0 and float(balance) < minimum_cash:
                state_class, dot_class = "warning", "dot-warn"
            else:
                state_class, dot_class = "positive", "dot-pos"

            if selected:
                state_class += " selected-range"

            lines: list[str] = []
            if mode in {"finance", "entries"}:
                lines.append(
                    f'<div class="calendar-line"><span>Entradas</span>'
                    f'<b class="calendar-in">{money_br(entries)}</b></div>'
                )
                lines.append(
                    f'<div class="calendar-line"><span>Em atraso</span>'
                    f'<b style="color:{WARNING}">{money_br(overdue)}</b></div>'
                )
            if mode in {"finance", "exits"}:
                exit_label = "Pago" if mode == "exits" and current_date < date.today() else "Saídas"
                exit_value_class = "calendar-in" if mode == "exits" and current_date < date.today() else "calendar-out"
                lines.append(
                    f'<div class="calendar-line"><span>{exit_label}</span>'
                    f'<b class="{exit_value_class}">{money_br(exits)}</b></div>'
                )
            if mode == "finance" and balance is not None:
                lines.append(
                    f'<div class="calendar-line"><span>Saldo</span>'
                    f'<b class="calendar-balance {"negative" if float(balance) < 0 else ""}">'
                    f'{money_br(float(balance))}</b></div>'
                )

            html.append(
                f'<div class="calendar-day {state_class}">'
                f'<div class="calendar-date"><span>{day_number:02d}</span>'
                f'<span class="status-dot {dot_class}"></span></div>'
                + "".join(lines)
                + "</div>"
            )

    html.append("</div></div>")
    st.markdown("".join(html), unsafe_allow_html=True)



def render_fullscreen_image(image_b64: str, alt: str) -> None:
    """Exibe a imagem e permite abri-la em uma nova aba, em tamanho integral."""
    data_uri = f"data:image/png;base64,{image_b64}"
    st.markdown(
        f'<a class="guide-image-link" href="{data_uri}" target="_blank" title="Clique para abrir em tela cheia">'
        f'<img src="{data_uri}" alt="{alt}"></a>',
        unsafe_allow_html=True,
    )


def styled_table(df: pd.DataFrame, money_cols: list[str], color_col: str | None = None, color: str = TEXT, height: int = 430):
    styler = df.style
    if money_cols:
        styler = styler.format({c: money_br for c in money_cols if c in df.columns})
    if color_col and color_col in df.columns:
        styler = styler.map(lambda _: f"color:{color};font-weight:800", subset=[color_col])
    st.dataframe(styler, use_container_width=True, hide_index=True, height=height)


def excel_bytes(detail: pd.DataFrame, daily: pd.DataFrame, weekly: pd.DataFrame, monthly: pd.DataFrame) -> bytes:
    output = io.BytesIO()
    with pd.ExcelWriter(output, engine="openpyxl") as writer:
        detail.to_excel(writer, sheet_name="Movimentos", index=False)
        daily.to_excel(writer, sheet_name="Fluxo Diário", index=False)
        weekly.to_excel(writer, sheet_name="Fluxo Semanal", index=False)
        monthly.to_excel(writer, sheet_name="Fluxo Mensal", index=False)
    return output.getvalue()




